def solve(input_data):
    nums = input_data["nums"]
    n = len(nums)

    class Node:
        __slots__ = ('l', 'r', 'sum', 'left', 'right')
        def __init__(self, l, r, sum=0, left=None, right=None):
            self.l = l
            self.r = r
            self.sum = sum
            self.left = left
            self.right = right

    def build(l, r):
        if l == r:
            return Node(l, r, nums[l], None, None)
        mid = (l + r) // 2
        left = build(l, mid)
        right = build(mid + 1, r)
        return Node(l, r, left.sum + right.sum, left, right)

    root = build(0, n - 1)

    def query(node, ql, qr):
        if ql <= node.l and node.r <= qr:
            return node.sum
        mid = (node.l + node.r) // 2
        res = 0
        if ql <= mid:
            res += query(node.left, ql, qr)
        if qr > mid:
            res += query(node.right, ql, qr)
        return res

    def update(node, index, value):
        if node.l == node.r:
            node.sum = value
            return
        mid = (node.l + node.r) // 2
        if index <= mid:
            update(node.left, index, value)
        else:
            update(node.right, index, value)
        node.sum = node.left.sum + node.right.sum

    l, r = input_data["query"]
    before = query(root, l, r)
    pos, val = input_data["update"]
    update(root, pos, val)
    after = query(root, l, r)
    return {"before": before, "after": after}
